-- =============================================================================
-- 000 — Esquema inicial (PostgreSQL / Supabase)
-- =============================================================================
-- Reproduz src/db/schema.sql já no estado atual do projeto.
-- As migrações 001 e 002 seguem em ficheiros próprios e são idempotentes.
--
-- Conversões face ao SQLite:
--   INTEGER AUTOINCREMENT  -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   INTEGER 0/1            -> BOOLEAN
--   TEXT (datas ISO)       -> TIMESTAMPTZ DEFAULT NOW()
--   PRAGMA foreign_keys    -> não é necessário (Postgres valida sempre)
--
-- Executar no SQL Editor do Supabase por esta ordem:
--   000, 001, 002, 003 (RLS) e 004 (seed).
-- =============================================================================

-- --------------------------------------------------------------------------
-- Utilizadores do painel e da cozinha
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS utilizadores (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome TEXT NOT NULL,
  username TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  papel TEXT NOT NULL CHECK (papel IN ('admin', 'cozinha')),
  deve_alterar_password BOOLEAN NOT NULL DEFAULT FALSE,
  ativo BOOLEAN NOT NULL DEFAULT TRUE,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- --------------------------------------------------------------------------
-- Configurações da aplicação (chave/valor)
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS configuracoes (
  chave TEXT PRIMARY KEY,
  valor TEXT NOT NULL
);

-- --------------------------------------------------------------------------
-- Categorias do menu
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categorias (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome TEXT NOT NULL,
  ordem INTEGER NOT NULL DEFAULT 0,
  ativo BOOLEAN NOT NULL DEFAULT TRUE,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- --------------------------------------------------------------------------
-- Pratos
-- foto          -> mantida por compatibilidade com o esquema SQLite
-- foto_url      -> URL pública da fotografia (bucket 'pratos' ou /uploads)
-- video_url     -> URL pública do vídeo (bucket 'videos-pratos' ou /uploads)
-- gostos        -> contador denormalizado (migração 001)
-- etiquetas     -> lista JSON guardada como texto, tal como no código atual
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pratos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome TEXT NOT NULL,
  descricao TEXT NOT NULL DEFAULT '',
  preco_centavos BIGINT NOT NULL CHECK (preco_centavos >= 0),
  foto TEXT,
  foto_url TEXT,
  video_url TEXT,
  tempo_preparo INTEGER NOT NULL DEFAULT 15,
  categoria_id BIGINT NOT NULL REFERENCES categorias(id) ON DELETE RESTRICT,
  disponivel BOOLEAN NOT NULL DEFAULT TRUE,
  etiquetas TEXT NOT NULL DEFAULT '[]',
  gostos INTEGER NOT NULL DEFAULT 0,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- --------------------------------------------------------------------------
-- Mesas
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS mesas (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  numero INTEGER NOT NULL UNIQUE,
  ativa BOOLEAN NOT NULL DEFAULT FALSE,
  codigo TEXT,
  criada_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- --------------------------------------------------------------------------
-- Sessões abertas pelos clientes ao ler o QR code da mesa
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sessoes_mesa (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mesa_id BIGINT NOT NULL REFERENCES mesas(id) ON DELETE CASCADE,
  token TEXT NOT NULL UNIQUE,
  aberta_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  fechada_em TIMESTAMPTZ,
  estado TEXT NOT NULL DEFAULT 'aberta' CHECK (estado IN ('aberta', 'fechada'))
);

CREATE INDEX IF NOT EXISTS idx_sessoes_mesa_aberta ON sessoes_mesa(mesa_id, estado);

-- --------------------------------------------------------------------------
-- Pedidos
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pedidos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mesa_id BIGINT NOT NULL REFERENCES mesas(id) ON DELETE RESTRICT,
  sessao_id BIGINT NOT NULL REFERENCES sessoes_mesa(id) ON DELETE RESTRICT,
  estado TEXT NOT NULL DEFAULT 'Recebido'
    CHECK (estado IN ('Recebido', 'Em preparo', 'Pronto', 'Entregue', 'Cancelado')),
  observacoes TEXT NOT NULL DEFAULT '',
  total_centavos BIGINT NOT NULL DEFAULT 0,
  tempo_previsto_min INTEGER NOT NULL DEFAULT 15,
  criado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_pedidos_estado ON pedidos(estado, criado_em);
CREATE INDEX IF NOT EXISTS idx_pedidos_sessao ON pedidos(sessao_id);
CREATE INDEX IF NOT EXISTS idx_pedidos_criado ON pedidos(criado_em);

-- --------------------------------------------------------------------------
-- Itens de cada pedido
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS itens_pedido (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  pedido_id BIGINT NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE,
  prato_id BIGINT REFERENCES pratos(id) ON DELETE SET NULL,
  nome_prato TEXT NOT NULL,
  quantidade INTEGER NOT NULL CHECK (quantidade > 0),
  preco_centavos BIGINT NOT NULL CHECK (preco_centavos >= 0),
  observacao TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_itens_pedido ON itens_pedido(pedido_id);

-- --------------------------------------------------------------------------
-- Chamadas de empregado / pedido da conta
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chamadas (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  mesa_id BIGINT NOT NULL REFERENCES mesas(id) ON DELETE CASCADE,
  sessao_id BIGINT REFERENCES sessoes_mesa(id) ON DELETE SET NULL,
  tipo TEXT NOT NULL CHECK (tipo IN ('empregado', 'conta')),
  estado TEXT NOT NULL DEFAULT 'pendente' CHECK (estado IN ('pendente', 'resolvida')),
  criada_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  resolvida_em TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_chamadas_pendentes ON chamadas(estado, criada_em);

-- --------------------------------------------------------------------------
-- Sessões web (express-session). expira_em guarda epoch em milissegundos.
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sessoes_web (
  sid TEXT PRIMARY KEY,
  sess TEXT NOT NULL,
  expira_em BIGINT NOT NULL
);
